code.perFrame:
reg01=ch1;
reg02=ch2;

inside=above(getkbmouse(1),-1)*below(getkbmouse(1),1)
              *above(getkbmouse(2),-1)*below(getkbmouse(2),1); 
funky=if(equal(locked+getkbmouse(3)+inside,3),bnot(funky),funky);
locked=1-getkbmouse(3);

posx=0;
posy=-1.5;

sinch=sinch+ch1;
cosch=cosch+ch2;

movx=pi*0.5;
movy=movy+sin(sinch+cosch)*0.01;
movz=0;

smovx=sin(movx);
smovy=sin(movy);
smovz=sin(movz);

cmovx=cos(movx);
cmovy=cos(movy);
cmovz=cos(movz);

num=0;

code.perPoint:
num=num+1;
x2d=(posx%5)*0.5-1;
posy=if(equal(posx%5,0),posy+0.5,posy);
y2d=posy;
z=0-0.8;

posx=posx+1;

x1=x2d*1.5;
y1=y2d*cmovx-z*smovx;
z1=y2d*smovx+z*cmovx;

x2=x1*cmovy+z1*smovy;
y2=y1;
z2=-x1*smovy+z1*cmovy;

x3=x2*cmovz-y2*smovz;
y3=x2*smovz+y2*cmovz;
z3=z2;

x=x3*(z3+2.3);
y=y3/(z3+2.3);

opac=(1/25)*num;

red=cred+if(equal(funky,1),getspec(opac,0.1,0)*5,0);
green=cgreen-if(equal(funky,1),getspec(opac,0.1,0)*5,0);
blue=cblue*if(equal(funky,1),getspec(opac,0.1,0)*5,1);

sizex=1.5-z3*0.8;
sizey=1.5-z3*0.8;
